(function(){var navToggle=document.querySelector(".nav-toggle");var nav=document.getElementById("site-nav");var year=document.getElementById("year");if(year){year.textContent=String(new Date().getFullYear());}if(navToggle && nav){navToggle.addEventListener("click",function(){var isOpen=nav.classList.toggle("open");navToggle.setAttribute("aria-expanded",String(isOpen));});nav.addEventListener("click",function(event){if(event.target.tagName !=="A")return;nav.classList.remove("open");navToggle.setAttribute("aria-expanded","false");});document.addEventListener("click",function(event){if(!nav.classList.contains("open"))return;if(nav.contains(event.target)|| navToggle.contains(event.target))return;nav.classList.remove("open");navToggle.setAttribute("aria-expanded","false");});document.addEventListener("keydown",function(event){if(event.key !=="Escape")return;if(!nav.classList.contains("open"))return;nav.classList.remove("open");navToggle.setAttribute("aria-expanded","false");navToggle.focus();});}var smoothLinks=document.querySelectorAll('a[href^="#"]');smoothLinks.forEach(function(link){link.addEventListener("click",function(event){var targetId=link.getAttribute("href");if(!targetId || targetId==="#")return;var target=document.querySelector(targetId);if(!target)return;event.preventDefault();target.scrollIntoView({behavior:"smooth",block:"start"});});});})();